const upsertWorkerPresenza = `-- name: UpsertWorkerPresenza :exec
INSERT INTO worker_presenza (worker_nome, worker_tipo, postazione_id, indirizzo_ip, ultimo_claim, outlook_ok,
                             caselle_aperte, ultimo_job_il, ultimo_arresto, avviso)
VALUES ($1, $2, $3, $4, now(),
        $5, $6::uuid[],
        CASE WHEN $7::boolean THEN now() END, $8, $9)
ON CONFLICT (worker_nome) DO UPDATE SET
    worker_tipo = EXCLUDED.worker_tipo, postazione_id = EXCLUDED.postazione_id,
    indirizzo_ip = EXCLUDED.indirizzo_ip, ultimo_claim = now(), outlook_ok = EXCLUDED.outlook_ok,
    caselle_aperte = EXCLUDED.caselle_aperte,
    ultimo_job_il  = COALESCE(EXCLUDED.ultimo_job_il, worker_presenza.ultimo_job_il),
    ultimo_arresto = COALESCE(EXCLUDED.ultimo_arresto, worker_presenza.ultimo_arresto),
    avviso         = EXCLUDED.avviso
`

type UpsertWorkerPresenzaParams struct {
	WorkerNome    string        `json:"worker_nome"`
	WorkerTipo    WorkerTipo    `json:"worker_tipo"`
	PostazioneID  uuid.NullUUID `json:"postazione_id"`
	IndirizzoIp   *netip.Addr   `json:"indirizzo_ip"`
	OutlookOk     bool          `json:"outlook_ok"`
	CaselleAperte []uuid.UUID   `json:"caselle_aperte"`
	ConJob        bool          `json:"con_job"`
	UltimoArresto pgtype.Text   `json:"ultimo_arresto"`
	Avviso        pgtype.Text   `json:"avviso"`
}

// Una riga per WORKER (0005): postazione e caselle vengono dalla credenziale intersecata con ciò che
// il worker dichiara, mai dal solo JSON. ultimo_arresto e avviso si conservano se il claim non ne
// porta di nuovi: sono informazioni che l'operatore deve poter leggere anche dopo il riavvio.
func (q *Queries) UpsertWorkerPresenza(ctx context.Context, arg UpsertWorkerPresenzaParams) error {
	_, err := q.db.Exec(ctx, upsertWorkerPresenza,
		arg.WorkerNome,
		arg.WorkerTipo,
		arg.PostazioneID,
		arg.IndirizzoIp,
		arg.OutlookOk,
		arg.CaselleAperte,
		arg.ConJob,
		arg.UltimoArresto,
		arg.Avviso,
	)
	return err
}

const verificaTentativo = `-- name: VerificaTentativo :one
SELECT job_id, tipo, worker_tipo, payload, chiave_idempotenza, stato, priorita, tentativi, max_tentativi, non_prima_di, lease_fino_a, worker_id, risultato, errore, creato_il, aggiornato_il, chiuso_il, casella_id, postazione_id, richiesto_da, lease_s, durata_max_s, lease_token, avviato_il, scade_il FROM job
WHERE job_id = $1
  AND stato = 'in_corso' AND lease_token = $2 AND worker_id = $3
  AND lease_fino_a > now() AND now() <= avviato_il + make_interval(secs => durata_max_s)
`

type VerificaTentativoParams struct {
	JobID      int64         `json:"job_id"`
	LeaseToken uuid.NullUUID `json:"lease_token"`
	WorkerID   pgtype.Text   `json:"worker_id"`
}

// Il predicato di validità SENZA blocco della riga: serve all'upload di un file (voce 2.3), che dura
// quanto un trasferimento e non può tenere una transazione aperta. Si verifica prima di cominciare a
// scrivere e di nuovo alla fine: un tentativo scaduto a metà trasferimento riceve 409 e il suo
// .parte.<token> viene rimosso. Non promuove nulla: la promozione a definitivo la fa solo il result,
// dentro la transazione, con BloccaTentativo.
func (q *Queries) VerificaTentativo(ctx context.Context, arg VerificaTentativoParams) (Job, error) {
	row := q.db.QueryRow(ctx, verificaTentativo, arg.JobID, arg.LeaseToken, arg.WorkerID)
	var i Job
	err := row.Scan(
		&i.JobID,
		&i.Tipo,
		&i.WorkerTipo,
		&i.Payload,
		&i.ChiaveIdempotenza,
		&i.Stato,
		&i.Priorita,
		&i.Tentativi,
		&i.MaxTentativi,
		&i.NonPrimaDi,
		&i.LeaseFinoA,
		&i.WorkerID,
		&i.Risultato,
		&i.Errore,
		&i.CreatoIl,
		&i.AggiornatoIl,
		&i.ChiusoIl,
		&i.CasellaID,
		&i.PostazioneID,
		&i.RichiestoDa,
		&i.LeaseS,
		&i.DurataMaxS,
		&i.LeaseToken,
		&i.AvviatoIl,
		&i.ScadeIl,
	)
	return i, err
}
